/*
 * 可直接双击 index.html 运行的浏览器脚本。
 * app.js、geometry.js、camera.js 仍保留为模块化学习源码；此文件避免 file://
 * 环境对 ES module import 的跨域限制，方便课程作业直接演示。
 */
(() => {
  const vec2 = (x, y) => [x, y];
  const mix = (a, b, t) => [a[0] * (1 - t) + b[0] * t, a[1] * (1 - t) + b[1] * t];
  const TRIANGLE = [vec2(-0.86, -0.74), vec2(0, 0.82), vec2(0.86, -0.74)];
  const createWebGL2Context = (canvas) => canvas.getContext('webgl2', { antialias: true, alpha: false });
  function initShaders(gl, vertexSource, fragmentSource) {
    const compile = (type, source) => { const s = gl.createShader(type); gl.shaderSource(s, source); gl.compileShader(s); if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s)); return s; };
    const p = gl.createProgram(); gl.attachShader(p, compile(gl.VERTEX_SHADER, vertexSource)); gl.attachShader(p, compile(gl.FRAGMENT_SHADER, fragmentSource)); gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p)); return p;
  }
  function chaosGame(vertices, count, ratio = .5) { const out = new Float32Array(count * 2); let p = vec2((Math.random() - .5) * .2, (Math.random() - .5) * .2), last = -1; const choose = () => { let i; do { i=Math.floor(Math.random()*vertices.length); } while(vertices.length>3&&last>=0&&(i===last||(i-last+vertices.length)%vertices.length===1||(last-i+vertices.length)%vertices.length===1)); last=i; return vertices[i]; }; for (let i = 0; i < 20; i++) p = mix(p, choose(), ratio); for (let i = 0; i < count; i++) { p = mix(p, choose(), ratio); out[i * 2] = p[0]; out[i * 2 + 1] = p[1]; } return out; }
  function polygonVertices(sides) { return Array.from({ length: sides }, (_, i) => { const a = Math.PI / 2 + i * Math.PI * 2 / sides; return vec2(Math.cos(a) * .82, Math.sin(a) * .82); }); }
  function sierpinski(depth) { const out = []; const add = (a,b,c) => out.push(...a,...b,...c); function subdivide(a,b,c,level) { if (!level) { add(a,b,c); return; } const ab=mix(a,b,.5), ac=mix(a,c,.5), bc=mix(b,c,.5); subdivide(a,ab,ac,level-1); subdivide(ab,b,bc,level-1); subdivide(ac,bc,c,level-1); } subdivide(...TRIANGLE,depth); return new Float32Array(out); }
  function triangleEdges(t) { const e = new Float32Array(t.length * 2); let k = 0; for (let i=0;i<t.length;i+=6) { const a=[t[i],t[i+1]], b=[t[i+2],t[i+3]], c=[t[i+4],t[i+5]]; for (const pair of [[a,b],[b,c],[c,a]]) { e[k++]=pair[0][0]; e[k++]=pair[0][1]; e[k++]=pair[1][0]; e[k++]=pair[1][1]; } } return e; }
  class PanZoom { constructor(){this.x=0;this.y=0;this.zoom=1;} pan(dx,dy){this.x+=dx/this.zoom;this.y+=dy/this.zoom;} scale(f){this.zoom=Math.min(8,Math.max(.35,this.zoom*f));} reset(){this.x=0;this.y=0;this.zoom=1;} }
  const VS = `#version 300 es\nin vec2 aPosition; uniform vec2 uPan; uniform float uZoom; uniform float uPointSize;\nvoid main(){ gl_Position=vec4((aPosition+uPan)*uZoom,0.0,1.0); gl_PointSize=uPointSize; }`;
  const FS = `#version 300 es\nprecision highp float; uniform vec3 uColor; out vec4 outColor;\nvoid main(){ outColor=vec4(uColor,1.); }`;
  const PALETTES = { aurora:[.26,.94,.81], sunset:[1,.46,.2], violet:[.69,.43,1] };
  class FractalApp {
    constructor() { this.canvas=document.querySelector('#glCanvas'); this.gl=createWebGL2Context(this.canvas); if(!this.gl){alert('浏览器不支持 WebGL 2.0。请使用最新版 Chrome、Edge 或 Firefox。');return;} const q=new URLSearchParams(location.search), mode=['points','lines','solid'].includes(q.get('mode'))?q.get('mode'):'points', algorithm=q.get('algorithm')==='recursive'?'recursive':'chaos'; this.captureMode=q.get('capture')==='1'; this.state={algorithm,sides:3,count:20000,depth:5,mode,pointSize:2.5,palette:'aurora',paused:false,visible:0}; this.camera=new PanZoom(); this.buffer=this.gl.createBuffer(); this.data=new Float32Array(); this.drag=null; this.program=initShaders(this.gl,VS,FS); this.locations=this.getLocations(); this.bindUI(); this.syncUI(); this.setMode(mode); this.resize(); this.regenerate(); requestAnimationFrame(this.frame.bind(this)); }
    getLocations(){const g=this.gl,p=this.program;return {position:g.getAttribLocation(p,'aPosition'),pan:g.getUniformLocation(p,'uPan'),zoom:g.getUniformLocation(p,'uZoom'),size:g.getUniformLocation(p,'uPointSize'),color:g.getUniformLocation(p,'uColor')};}
    bindUI(){const q=s=>document.querySelector(s); document.querySelectorAll('[data-alg]').forEach(b=>b.onclick=()=>{this.state.algorithm=b.dataset.alg;this.syncUI();this.regenerate();}); q('#shape').onchange=e=>{this.state.sides=+e.target.value;if(this.state.sides!==3&&this.state.algorithm==='recursive'){this.state.algorithm='chaos';this.syncUI();this.setMode('points');}else this.regenerate();}; q('#count').oninput=e=>{this.state.count=+e.target.value;q('#countOut').textContent=this.state.count.toLocaleString();this.regenerate();}; q('#depth').oninput=e=>{this.state.depth=+e.target.value;q('#depthOut').textContent=this.state.depth;this.regenerate();}; q('#pointSize').oninput=e=>{this.state.pointSize=+e.target.value;q('#sizeOut').textContent=`${this.state.pointSize} px`;}; q('#palette').onchange=e=>this.state.palette=e.target.value; document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>this.setMode(b.dataset.mode)); q('#pause').onclick=()=>this.togglePause();q('#reset').onclick=()=>this.camera.reset();this.canvas.addEventListener('mousedown',e=>{this.drag={x:e.clientX,y:e.clientY};this.canvas.style.cursor='grabbing';});window.addEventListener('mouseup',()=>{this.drag=null;this.canvas.style.cursor='grab';});window.addEventListener('mousemove',e=>{if(!this.drag)return;this.camera.pan((e.clientX-this.drag.x)/this.canvas.clientWidth*2,(this.drag.y-e.clientY)/this.canvas.clientHeight*2);this.drag={x:e.clientX,y:e.clientY};});this.canvas.addEventListener('wheel',e=>{e.preventDefault();this.camera.scale(e.deltaY>0?.88:1.14);},{passive:false});window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();this.togglePause();}if(['1','2','3'].includes(e.key))this.setMode({1:'points',2:'lines',3:'solid'}[e.key]);});window.addEventListener('resize',()=>this.resize());}
    syncUI(){const r=this.state.algorithm==='recursive';document.querySelectorAll('[data-alg]').forEach(b=>b.classList.toggle('active',b.dataset.alg===this.state.algorithm));document.querySelector('#countControl').hidden=r;document.querySelector('#depthControl').hidden=!r;document.querySelector('#algorithmNote').textContent=r?'每次细分一个三角形的三条边中点，保留三个角上的子三角形。':this.state.sides===3?'随机选一个顶点，将当前点向它移动一半。重复后得到 Sierpinski 垫片。':'多边形扩展：每次避开上一次的相邻顶点，再向选中顶点移动一半，形成不同的 n 边形垫片。';}
    setMode(m){if(m!=='points'&&this.state.algorithm==='chaos'){this.state.algorithm='recursive';this.syncUI();}this.state.mode=m;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));this.regenerate();}
    togglePause(){this.state.paused=!this.state.paused;document.querySelector('#pause').innerHTML=this.state.paused?'继续生长 <kbd>Space</kbd>':'暂停生长 <kbd>Space</kbd>';document.querySelector('#statusText').textContent=this.state.paused?'已暂停':'逐点生长中';}
    regenerate(){this.state.visible=0;const s=this.state;this.data=s.algorithm==='chaos'?chaosGame(polygonVertices(s.sides),s.count):(()=>{const f=sierpinski(s.depth);return s.mode==='lines'?triangleEdges(f):f;})();if(this.captureMode)this.state.visible=this.data.length/2;this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.buffer);this.gl.bufferData(this.gl.ARRAY_BUFFER,this.data,this.gl.STATIC_DRAW);}
    resize(){const d=Math.min(devicePixelRatio,2),w=this.canvas.clientWidth*d,h=this.canvas.clientHeight*d;if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;}this.gl.viewport(0,0,w,h);}
    frame(){if(!this.state.paused&&this.state.visible<this.data.length/2)this.state.visible=Math.min(this.data.length/2,this.state.visible+Math.max(90,this.data.length/240));this.draw();requestAnimationFrame(this.frame.bind(this));}
    draw(){const g=this.gl,s=this.state;g.clearColor(.027,.075,.11,1);g.clear(g.COLOR_BUFFER_BIT);g.useProgram(this.program);g.bindBuffer(g.ARRAY_BUFFER,this.buffer);g.enableVertexAttribArray(this.locations.position);g.vertexAttribPointer(this.locations.position,2,g.FLOAT,false,0,0);g.uniform2f(this.locations.pan,this.camera.x,this.camera.y);g.uniform1f(this.locations.zoom,this.camera.zoom);g.uniform1f(this.locations.size,s.pointSize*devicePixelRatio);g.uniform3fv(this.locations.color,PALETTES[s.palette]);let p=g.POINTS;if(s.algorithm==='recursive')p=s.mode==='lines'?g.LINES:s.mode==='solid'?g.TRIANGLES:g.POINTS;g.drawArrays(p,0,Math.floor(s.visible));}
  }
  new FractalApp();
})();
